    key:
      input?.key ??
      typia.random<
        string &
          tags.MinLength<1> &
          tags.MaxLength<50> &
          tags.Pattern<"^[a-z_]+$">
      >(),
    value:
      input?.value ??
      RandomGenerator.paragraph({
        sentences: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<2> & tags.Maximum<5>
        >(),
        wordMin: 5,
        wordMax: 10,
      }),
    description:
      input?.description ?? RandomGenerator.paragraph({ sentences: 2 }),
  };
}

